fn load_theme_from_file(path: &str) -> Result<Theme, String> {
    let content = fs::read_to_string(path)
        .map_err(|e| format!("Could not read theme file: {}", e))?;

    let theme: Theme = serde_yaml::from_str(&content)
        .map_err(|e| format!("Could not parse yaml for theme: {}", e))?;

    Ok(theme)
}

fn get_config_path(cli_config: &Option<String>) -> String {
    cli_config.clone().unwrap_or_else(get_default_config_path)
}

fn apply_theme_to_config(config: &str, theme: &Theme) -> String {
    let mut result = config.to_string();

    // Add client colors
    if let Some(colors) = &theme.colors {
        if let Some(client_focused) = colors.get("client.focused") {
            result.push_str(&format!("\nclient.focused {} {}\n", 
                client_focused.join(" "),
                client_focused[client_focused.len()-1].clone()));
        }
        if let Some(client_focused_inactive) = colors.get("client.focused_inactive") {
            result.push_str(&format!("\nclient.focused_inactive {} {}\n", 
                client_focused_inactive.join(" "),
                client_focused_inactive[client_focused_inactive.len()-1].clone()));
        }
        if let Some(client_unfocused) = colors.get("client.unfocused") {
            result.push_str(&format!("\nclient.unfocused {} {}\n", 
                client_unfocused.join(" "),
                client_unfocused[client_unfocused.len()-1].clone()));
        }
        if let Some(client_urgent) = colors.get("client.urgent") {
            result.push_str(&format!("\nclient.urgent {} {}\n", 
                client_urgent.join(" "),
                client_urgent[client_urgent.len()-1].clone()));
        }
    }

    // Add bar colors if there's a bar section
    if result.contains("bar {") {
        if let Some(bar_colors) = &theme.bar_colors {
            if let Some(focused) = bar_colors.get("focused_workspace") {
                result.push_str(&format!("\n    focused_workspace {} {}\n", 
                    focused.join(" "),
                    focused[focused.len()-1].clone()));
            }
            if let Some(active) = bar_colors.get("active_workspace") {
                result.push_str(&format!("\n    active_workspace {} {}\n", 
                    active.join(" "),
                    active[active.len()-1].clone()));
            }
            if let Some(inactive) = bar_colors.get("inactive_workspace") {
                result.push_str(&format!("\n    inactive_workspace {} {}\n", 
                    inactive.join(" "),
                    inactive[inactive.len()-1].clone()));
            }
            if let Some(urgent) = bar_colors.get("urgent_workspace") {
                result.push_str(&format!("\n    urgent_workspace {} {}\n", 
                    urgent.join(" "),
                    urgent[urgent.len()-1].clone()));
            }
        }
    }

    result
}

fn main() {
    let cli = Cli::parse();

    if cli.list_all {
        print_available_themes();
        return;
    }

    if cli.help {
        print_help();
        return;
    }

    if cli.version {
        println!("i3-style 1.0");
        return;
    }

    // Get the theme
    let theme = match &cli.theme {
        Some(theme_name) => {
            if Path::new(theme_name).is_file() {
                match load_theme_from_file(theme_name) {
                    Ok(theme) => theme,
                    Err(e) => {
                        eprintln!("{}", e);
                        process::exit(101);
                    }
                }
            } else {
                match get_theme_from_name(theme_name) {
                    Some(theme) => theme,
                    None => {
                        eprintln!("Could not find theme '{}'", theme_name);
                        process::exit(1);
                    }
                }
            }
        }
        None => {
            eprintln!("Select a theme as the first argument. Use `--list-all` to see the themes.");
            process::exit(1);
        }
    };

    // Get the config path
    let config_path = get_config_path(&cli.config);

    // Read the config
    let config_content = match fs::read_to_string(&config_path) {
        Ok(content) => content,
        Err(e) => {
            eprintln!("Could not find i3 config");
            eprintln!("{}", e);
            process::exit(1);
        }
    };

    // Apply the theme
    let result = apply_theme_to_config(&config_content, &theme);

    // Handle --to-theme
    if cli.to_theme.is_some() {
        // Extract colors from config
        let colors = extract_colors_from_config(&config_content);
        let bar_colors = extract_bar_colors_from_config(&config_content);
        let window_colors = extract_window_colors_from_config(&config_content);

        let theme_output = format!(
            "---\nmeta:\n  description: AUTOMATICALLY GENERATED THEME\ncolors: {}\nwindow_colors: {}\nbar_colors: {}\n",
            serde_yaml::to_string(&colors).unwrap_or_default(),
            serde_yaml::to_string(&window_colors).unwrap_or_default(),
            serde_yaml::to_string(&bar_colors).unwrap_or_default()
        );
        print!("{}", theme_output);
        return;
    }

    // Handle --save
    if cli.save {
        let output_path = config_path.clone();
        save_config(&output_path, &result);
        println!("saving config at {} to {}", config_path, output_path);
        return;
    }

    // Handle --output
    if let Some(output_path) = &cli.output {
        save_config(output_path, &result);
        println!("saving config at {} to {}", config_path, output_path);
        return;
    }

    // Handle --reload
    if cli.reload {
        reload_config(&config_path);
    }

    // Print the result
    print!("{}", result);
}

