    println!("    -t, --to-theme <file>    Prints an i3-style theme based on the given config suitable for sharing with others");
    println!("                             [default: ]");
    println!();
    println!("ARGS:");
    println!("    <theme>    The theme to use");
}

fn save_config(path: &str, content: &str) {
    let mut file = fs::File::create(path).expect("Could not create output file");
    file.write_all(content.as_bytes()).expect("Could not write to output file");
}

fn reload_config(path: &str) {
    // Try to reload with i3-msg
    let output = std::process::Command::new("i3-msg")
        .arg("reload")
        .output();

    if let Ok(out) = output {
        if !out.status.success() {
            eprintln!("Could not reload config with i3-msg: {}", 
                String::from_utf8_lossy(&out.stderr));
        }
    }
}

fn extract_colors_from_config(config: &str) -> HashMap<String, Vec<String>> {
    let mut colors = HashMap::new();

    // Extract client colors
    if let Some(client_focused) = extract_value(config, "client.focused") {
        colors.insert("client.focused".to_string(), client_focused);
    }
    if let Some(client_focused_inactive) = extract_value(config, "client.focused_inactive") {
        colors.insert("client.focused_inactive".to_string(), client_focused_inactive);
    }
    if let Some(client_unfocused) = extract_value(config, "client.unfocused") {
        colors.insert("client.unfocused".to_string(), client_unfocused);
    }
    if let Some(client_urgent) = extract_value(config, "client.urgent") {
        colors.insert("client.urgent".to_string(), client_urgent);
    }

    colors
}

fn extract_bar_colors_from_config(config: &str) -> HashMap<String, Vec<String>> {
    let mut bar_colors = HashMap::new();

    if let Some(focused) = extract_value(config, "focused_workspace") {
        bar_colors.insert("focused_workspace".to_string(), focused);
    }
    if let Some(active) = extract_value(config, "active_workspace") {
        bar_colors.insert("active_workspace".to_string(), active);
    }
    if let Some(inactive) = extract_value(config, "inactive_workspace") {
        bar_colors.insert("inactive_workspace".to_string(), inactive);
    }
    if let Some(urgent) = extract_value(config, "urgent_workspace") {
        bar_colors.insert("urgent_workspace".to_string(), urgent);
    }

    bar_colors
}

fn extract_window_colors_from_config(config: &str) -> HashMap<String, Vec<String>> {
    let mut window_colors = HashMap::new();

    if let Some(focused) = extract_value(config, "focused") {
        window_colors.insert("focused".to_string(), focused);
    }
    if let Some(focused_inactive) = extract_value(config, "focused_inactive") {
        window_colors.insert("focused_inactive".to_string(), focused_inactive);
    }
    if let Some(unfocused) = extract_value(config, "unfocused") {
        window_colors.insert("unfocused".to_string(), unfocused);
    }
    if let Some(urgent) = extract_value(config, "urgent") {
        window_colors.insert("urgent".to_string(), urgent);
    }

    window_colors
}

fn extract_value(config: &str, key: &str) -> Option<Vec<String>> {
    let lines: Vec<&str> = config.lines().collect();
    for line in lines {
        if line.starts_with(key) {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 2 {
                let values: Vec<String> = parts[1..].iter().map(|s| s.to_string()).collect();
                return Some(values);
            }
        }
    }
    None
}
