}

fn get_theme_from_name(name: &str) -> Option<Theme> {
    match name.to_lowercase().as_str() {
        "slate" => Some(slate_theme()),
        "alphare" => Some(alphare_theme()),
        "ubuntu" => Some(ubuntu_theme()),
        "flat-gray" => Some(flat_gray_theme()),
        "purple" => Some(purple_theme()),
        "archlinux" => Some(archlinux_theme()),
