}

fn get_default_config_path() -> String {
    let home = std::env::var("HOME").unwrap_or_else(|_| "/home/user".to_string());
    format!("{}/.config/i3/config", home)
}

fn get_theme_from_name(name: &str) -> Option<Theme> {
    match name.to_lowercase().as_str() {
        "slate" => Some(slate_theme()),
        "alphare" => Some(alphare_theme()),
        "ubuntu" => Some(ubuntu_theme()),
        "flat-gray" => Some(flat_gray_theme()),
        "purple" => Some(purple_theme()),
        "archlinux" => Some(archlinux_theme()),
        "default" => Some(default_theme()),
        "debian" => Some(debian_theme()),
        "oceanic-next" => Some(oceanic_next_theme()),
        "base16-tomorrow" => Some(base16_tomorrow_theme()),
        "okraits" => Some(okraits_theme()),
