use std::env;
use std::fs;
use std::io::Write;

fn get_default_config_path() -> String {
    let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
    format!("{}/.config/i3/config", home)
}

fn get_available_themes() -> Vec<String> {
    vec![
        "slate".to_string(),
        "alphare".to_string(),
        "ubuntu".to_string(),
        "flat-gray".to_string(),
        "purple".to_string(),
        "archlinux".to_string(),
        "default".to_string(),
        "debian".to_string(),
        "oceanic-next".to_string(),
        "base16-tomorrow".to_string(),
        "okraits".to_string(),
        "icelines".to_string(),
        "solarized".to_string(),
        "deep-purple".to_string(),
        "tomorrow-night-80s".to_string(),
        "seti".to_string(),
        "lime".to_string(),
        "gruvbox".to_string(),
        "mate".to_string(),
    ]
}

fn parse_config(content: &str) -> HashMap<String, Vec<String>> {
    let mut config = HashMap::new();
    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("statusline") {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 2 {
                let values: Vec<String> = parts[1..].iter().map(|s| s.to_string()).collect();
                config.insert("statusline".to_string(), values);
            }
        } else if line.starts_with("bar") {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 2 {
                let values: Vec<String> = parts[1..].iter().map(|s| s.to_string()).collect();
                config.insert("bar".to_string(), values);
            }
        }
    }
    config
}

fn parse_bar_colors(content: &str) -> HashMap<String, Vec<String>> {
    let mut colors = HashMap::new();
    let mut in_colors = false;
    let mut current_key = String::new();
    let mut current_values: Vec<String> = Vec::new();

    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("colors") {
            in_colors = true;
            continue;
        }
        if in_colors {
            if line.starts_with("}") {
                if !current_key.is_empty() {
                    colors.insert(current_key.clone(), current_values.clone());
                }
                in_colors = false;
                current_key = String::new();
                current_values.clear();
                continue;
            }
            if line.starts_with("    ") || line.starts_with("  ") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 2 {
                    current_key = parts[0].to_string();
                    current_values = parts[1..].iter().map(|s| s.to_string()).collect();
                }
            }
        }
    }
    colors
}

fn parse_client_colors(content: &str) -> HashMap<String, Vec<String>> {
    let mut colors = HashMap::new();
    let mut in_client = false;
    let mut current_key = String::new();
    let mut current_values: Vec<String> = Vec::new();

    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("client") {
            in_client = true;
            continue;
        }
        if in_client {
            if line.starts_with("}") {
                if !current_key.is_empty() {
                    colors.insert(current_key.clone(), current_values.clone());
                }
                in_client = false;
                current_key = String::new();
                current_values.clear();
                continue;
            }
            if line.starts_with("    ") || line.starts_with("  ") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 2 {
                    current_key = parts[0].to_string();
                    current_values = parts[1..].iter().map(|s| s.to_string()).collect();
                }
            }
        }
    }
    colors
}

