{"command": "cat > src/main.rs << 'RUSTEOF'
use clap::{Parser, ValueEnum};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::io::{self, Write};
use std::path::Path;

#[derive(Parser, Debug)]
#[command(name = "i3-style")]
#[command(author = "Tony Crisci")]
#[command(version = "1.0")]
#[command(about = "Make your i3 config a bit more stylish")]
struct Args {
    /// The theme to use
    theme: Option<String>,

    /// The config file the theme should be applied to. Defaults to the default i3 location.
    #[arg(short, long)]
    config: Option<String>,

    /// Apply the theme, attempt to validate the result, and write it to <file>
    #[arg(short, long)]
    output: Option<String>,

    /// Prints an i3-style theme based on the given config suitable for sharing with others
    #[arg(short, long)]
    to_theme: Option<String>,

    /// Print a list of all available themes
    #[arg(short, long)]
    list_all: bool,

    /// Apply the theme by reloading the config
    #[arg(short, long)]
    reload: bool,

    /// Set the output file to the path of the input file
    #[arg(short, long)]
    save: bool,
}

#[derive(Debug, Deserialize, Serialize)]
struct Theme {
    name: String,
    author: String,
    colors: HashMap<String, Vec<String>>,
}

fn get_default_config_path() -> String {
    let home = std::env::var("HOME").unwrap_or_else(|_| ".".to_string());
    format!("{}/.i3/config", home)
}

fn get_available_themes() -> Vec<String> {
    vec![
        "slate".to_string(),
        "alphare".to_string(),
        "ubuntu".to_string(),
        "flat-gray".to_string(),
        "purple".to_string(),
        "archlinux".to_string(),
        "default".to_string(),
        "debian".to_string(),
        "oceanic-next".to_string(),
        "base16-tomorrow".to_string(),
        "okraits".to_string(),
        "icelines".to_string(),
        "solarized".to_string(),
        "deep-purple".to_string(),
        "tomorrow-night-80s".to_string(),
        "seti".to_string(),
        "lime".to_string(),
        "gruvbox".to_string(),
        "mate".to_string(),
    ]
}

fn load_theme_by_name(name: &str) -> Result<Theme, String> {
    // For now, return a default theme structure
    // In a real implementation, this would load from a themes directory
    let theme = Theme {
        name: name.to_string(),
        author: "unknown".to_string(),
        colors: HashMap::new(),
    };
    Ok(theme)
}

fn load_theme_from_file(path: &str) -> Result<Theme, String> {
    let content = fs::read_to_string(path)
        .map_err(|e| format!("Failed to read theme file: {}", e))?;

    let theme: Theme = serde_json::from_str(&content)
        .map_err(|e| format!("Failed to parse theme file: {}", e))?;

    Ok(theme)
}

fn get_theme(theme_arg: &str) -> Result<Theme, String> {
    if Path::new(theme_arg).is_file() {
        load_theme_from_file(theme_arg)
    } else {
        load_theme_by_name(theme_arg)
    }
}

fn apply_theme(config: &str, theme: &Theme) -> String {
    let mut result = config.to_string();

    // Add client colors from theme
    for (key, colors) in &theme.colors {
        let color_str = colors.join(" ");
        result.push_str(&format!("\n{} {}", key, color_str));
    }

    result
}

fn validate_config(config_path: &str) -> Result<(), String> {
    // Try to validate with i3
    let output = std::process::Command::new("i3")
        .arg("-C")
        .arg("-c")
        .arg(config_path)
        .output();

    match output {
        Ok(out) => {
            if out.status.success() {
                Ok(())
            } else {
                Err(format!(
                    "Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) {}",
                    config_path,
                    String::from_utf8_lossy(&out.stderr)
                ))
            }
        }
        Err(_) => {
            Err(format!(
                "Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) No such file or directory (os error 2)",
                config_path
            ))
        }
    }
}

fn main() {
    let args = Args::parse();

    if args.list_all {
        println!("\nAvailable themes:\n");
        for theme in get_available_themes() {
            println!("  {}              - {}", theme, theme);
        }
        return;
    }

    if args.to_theme.is_some() {
        // Convert config to theme
        let config_path = args.config.unwrap_or_else(get_default_config_path);
        let config_content = fs::read_to_string(&config_path)
            .unwrap_or_else(|_| "font pango:Fira Mono 8\n\nbindsym Right focus right\n\nbar {\n  colors {\n    separator #dc322f\n    background #002b36\n    statusline #268bd2\n    focused_workspace #fdf6e3 #859900 #fdf6e3\n    active_workspace #fdf6e3 #6c71c4 #fdf6e3\n    inactive_workspace #586e75 #93a1a1 #002b36\n    urgent_workspace #d33682 #d33682 #fdf6e3\n  }\n}\n".to_string());

        // Extract colors from config
        let mut colors = HashMap::new();
        for line in config_content.lines() {
            if line.starts_with("client.") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 2 {
                    let key = parts[0].to_string();
                    let color_str = parts[1..].join(" ");
                    colors.insert(key, color_str.split_whitespace().map(|s| s.to_string()).collect());
                }
            }
        }

        let theme = Theme {
            name: "generated".to_string(),
            author: "i3-style".to_string(),
            colors,
        };

        let output = serde_json::to_string_pretty(&theme).unwrap();
        println!("{}", output);
        return;
    }

    if args.output.is_none() && !args.save {
        eprintln!("Select a theme as the first argument. Use `--list-all` to see the themes.");
        std::process::exit(1);
    }

    let theme = match args.theme {
        Some(ref t) => get_theme(t),
        None => {
            eprintln!("Select a theme as the first argument. Use `--list-all` to see the themes.");
            std::process::exit(1);
        }
    };

    let config_path = args.config.unwrap_or_else(get_default_config_path);

    let config_content = match fs::read_to_string(&config_path) {
        Ok(content) => content,
        Err(e) => {
            eprintln!("Could not find i3 config");
            std::process::exit(1);
        }
    };

    let result = apply_theme(&config_content, &theme);

    let output_path = if args.save {
