fn load_theme_from_file(path: &str) -> Result<HashMap<String, Vec<String>>, String> {
    let content = fs::read_to_string(path)
        .map_err(|e| format!("Failed to read theme file: {}", e))?;

    let mut colors = HashMap::new();
    let mut current_key: Option<String> = None;

    for line in content.lines() {
        let line = line.trim();
        if line.starts_with('"') && line.ends_with('"') {
            let key = line[1..line.len()-1].to_string();
            current_key = Some(key);
        } else if line.starts_with('"') {
            let value = line[1..].trim_matches('"').to_string();
            if let Some(ref k) = current_key {
                colors.entry(k.clone()).or_insert_with(Vec::new).push(value);
            }
        }
    }

    Ok(colors)
}

fn get_theme(theme_arg: &str) -> HashMap<String, Vec<String>> {
    if Path::new(theme_arg).is_file() {
        match load_theme_from_file(theme_arg) {
            Ok(t) => t,
            Err(_) => HashMap::new(),
        }
    } else {
        // Look up built-in theme
        for (name, colors) in THEMES {
            if name == theme_arg {
                let mut result = HashMap::new();
                for (key, values) in colors {
                    result.insert(key.to_string(), values.iter().map(|v| v.to_string()).collect());
                }
                return result;
            }
        }
        HashMap::new()
    }
}

fn apply_theme(config: &str, theme: &HashMap<String, Vec<String>>) -> String {
    let mut result = config.to_string();

    for (key, colors) in theme {
        let color_str = colors.join(" ");
        result.push_str(&format!("\n{} {}", key, color_str));
    }

    result
}

fn validate_config(config_path: &str) -> Result<(), String> {
    let output = std::process::Command::new("i3")
        .arg("-C")
        .arg("-c")
        .arg(config_path)
        .output();

    match output {
        Ok(out) => {
            if out.status.success() {
                Ok(())
            } else {
                Err(format!(
                    "Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) {}",
                    config_path,
                    String::from_utf8_lossy(&out.stderr)
                ))
            }
        }
        Err(_) => {
            Err(format!(
                "Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) No such file or directory (os error 2)",
                config_path
            ))
        }
    }
}

fn to_json_string(map: &HashMap<String, Vec<String>>) -> String {
    let mut result = String::from("{\n");
    let mut first = true;

    for (key, values) in map {
        if !first {
            result.push_str(",\n");
        }
        first = false;

        result.push_str(&format!("  \"{}\": [", key));
        for (i, val) in values.iter().enumerate() {
            if i > 0 {
                result.push_str(", ");
            }
            result.push_str(&format!("\"{}\"", val));
        }
        result.push_str("]");
    }

    result.push_str("\n}");
    result
}

fn print_help() {
    println!("i3-style 1.0");
    println!("Make your i3 config a bit more stylish");
    println!();
    println!("USAGE:");
    println!("    executable [FLAGS] [OPTIONS] [theme]");
    println!();
    println!("FLAGS:");
    println!("    -h, --help        Prints help information");
    println!("    -l, --list-all    Print a list of all available themes");
    println!("    -r, --reload      Apply the theme by reloading the config");
    println!("    -s, --save        Set the output file to the path of the input file");
    println!("    -V, --version     Prints version information");
    println!();
    println!("OPTIONS:");
    println!("    -c, --config <file>      The config file the theme should be applied to. Defaults to the default i3 location.");
    println!("    -o, --output <file>      Apply the theme, attempt to validate the result, and write it to <file>");
    println!("    -t, --to-theme <file>    Prints an i3-style theme based on the given config suitable for sharing with others");
    println!("                             [default: ]");
    println!();
    println!("ARGS:");
    println!("    <theme>    The theme to use");
}

fn print_version() {
    println!("i3-style 1.0");
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_help();
        std::process::exit(1);
    }

    let mut i = 1;
    let mut theme = None;
    let mut config = None;
    let mut output: Option<String> = None;
    let mut to_theme = None;
    let mut list_all = false;
    let mut reload = false;
    let mut save = false;

    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "-h" | "--help" => {
                print_help();
                std::process::exit(0);
            }
            "-l" | "--list-all" => {
                list_all = true;
            }
            "-r" | "--reload" => {
                reload = true;
            }
            "-s" | "--save" => {
                save = true;
            }
            "-V" | "--version" => {
                print_version();
                std::process::exit(0);
            }
            "-c" | "--config" => {
                if i + 1 < args.len() {
                    config = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            "-o" | "--output" => {
                if i + 1 < args.len() {
                    output = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            "-t" | "--to-theme" => {
                if i + 1 < args.len() {
                    to_theme = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            _ => {
                if theme.is_none() {
                    theme = Some(arg.clone());
                } else {
                    eprintln!("Select a theme as the first argument. Use `--list-all` to see the themes.");
                    std::process::exit(1);
                }
            }
        }
        i += 1;
    }

    if list_all {
        println!("\nAvailable themes:\n");
        for theme_name in get_available_themes() {
            println!("  {}              - {}", theme_name, theme_name);
        }
        return;
    }

    if to_theme.is_some() {
        let config_path = config.unwrap_or_else(get_default_config_path);
        let config_content = match fs::read_to_string(&config_path) {
            Ok(content) => content,
            Err(e) => {
                eprintln!("Could not find i3 config");
                std::process::exit(1);
            }
        };

        let mut colors = HashMap::new();
        for line in config_content.lines() {
            if line.starts_with("client.") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 2 {
                    let key = parts[0].to_string();
                    let color_str = parts[1..].join(" ");
                    colors.insert(key, color_str.split_whitespace().map(|s| s.to_string()).collect());
                }
            }
        }

        let output_str = to_json_string(&colors);
        println!("{}", output_str);
        return;
    }

    if output.is_none() && !save {
        eprintln!("Select a theme as the first argument. Use `--list-all` to see the themes.");
        std::process::exit(1);
    }

    let theme = get_theme(theme.as_ref().unwrap());

    let config_path = config.unwrap_or_else(get_default_config_path);

    let config_content = match fs::read_to_string(&config_path) {
        Ok(content) => content,
        Err(e) => {
            eprintln!("Could not find i3 config");
            std::process::exit(1);
        }
    };

    let result = apply_theme(&config_content, &theme);

    let output_path = if save {
        config_path.clone()
    } else {
        output.clone().unwrap_or_else(|| {
            eprintln!("Please specify an output file with -o or --output");
            std::process::exit(1);
        })
    };

    if output.is_some() {
        if let Err(_) = validate_config(&output_path) {
            eprintln!("Could not validate config");
            std::process::exit(1);
        }
    }

    let mut file = match fs::File::create(&output_path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Failed to create output file: {}", e);
            std::process::exit(1);
        }
    };

    if let Err(e) = file.write_all(result.as_bytes()) {
        eprintln!("Failed to write output file: {}", e);
        std::process::exit(1);
    }

    println!("saving config at {} to {}", config_path, output_path);
}
