fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_help();
        std::process::exit(1);
    }

    let mut i = 1;
    let mut theme = None;
    let mut config = None;
    let mut output: Option<String> = None;
    let mut to_theme = None;
    let mut list_all = false;
    let mut reload = false;
    let mut save = false;

    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "-h" | "--help" => {
                print_help();
                std::process::exit(0);
            }
            "-l" | "--list-all" => {
                list_all = true;
            }
            "-r" | "--reload" => {
                reload = true;
            }
            "-s" | "--save" => {
                save = true;
            }
            "-V" | "--version" => {
                print_version();
                std::process::exit(0);
            }
            "-c" | "--config" => {
                if i + 1 < args.len() {
                    config = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            "-o" | "--output" => {
                if i + 1 < args.len() {
                    output = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            "-t" | "--to-theme" => {
                if i + 1 < args.len() {
                    to_theme = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            _ => {
                if theme.is_none() {
                    theme = Some(arg.clone());
                } else {
                    eprintln!("Select a theme as the first argument. Use `--list-all` to see the themes.");
                    std::process::exit(1);
                }
            }
        }
        i += 1;
    }

    if list_all {
        println!("\nAvailable themes:\n");
        for theme_name in get_available_themes() {
            println!("  {}              - {}", theme_name, theme_name);"}

