    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_help();
        std::process::exit(1);
    }

    let mut i = 1;
    let mut theme = None;
    let mut config = None;
    let mut output: Option<String> = None;
    let mut to_theme = None;
    let mut list_all = false;
    let mut reload = false;
    let mut save = false;

    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "-h" | "--help" => {
                print_help();
                std::process::exit(0);
            }
            "-l" | "--list-all" => {
                list_all = true;
            }
            "-r" | "--reload" => {
                reload = true;
            }
            "-s" | "--save" => {
                save = true;
            }
            "-V" | "--version" => {
                print_version();
                std::process::exit(0);
            }
            "-c" | "--config" => {
                if i + 1 < args.len() {
                    config = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            "-o" | "--output" => {
                if i + 1 < args.len() {
                    output = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            "-t" | "--to-theme" => {
                if i + 1 < args.len() {
                    to_theme = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            _ => {
                if theme.is_none() {
                    theme = Some(arg.clone());
                } else {
                    eprintln!("Select a theme as the first argument. Use `--list-all` to see the themes.");
                    std::process::exit(1);
                }
            }
        }
        i += 1;
    }

    if list_all {
        println!("\nAvailable themes:\n");
        for theme_name in get_available_themes() {
            println!("  {}              - {}", theme_name, theme_name);
        }
        std::process::exit(0);
    }

    let theme_arg = theme.unwrap_or_else(|| "default".to_string());

    if let Some(ref to_theme_path) = to_theme {
        let config_content = match fs::read_to_string(&config.unwrap_or_else(|| get_default_config_path())) {
            Ok(content) => content,
            Err(e) => {
                eprintln!("Error reading config file: {}", e);
                std::process::exit(1);
            }
        };

        let mut result = HashMap::new();
        for line in config_content.lines() {
            let line = line.trim();
            if line.starts_with("statusline") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 2 {
                    let values: Vec<String> = parts[1..].iter().map(|s| s.to_string()).collect();
                    result.insert("statusline".to_string(), values);
                }
            } else if line.starts_with("bar") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 2 {
                    let values: Vec<String> = parts[1..].iter().map(|s| s.to_string()).collect();
                    result.insert("bar".to_string(), values);
                }
            }
        }

        let json = to_json_string(&result);
        println!("{}", json);
        std::process::exit(0);
    }

    let theme_data = THEMES.iter().find(|(name, _)| *name == theme_arg);

    if let Some((_, theme_colors)) = theme_data {
        let mut result = HashMap::new();
        for (key, values) in theme_colors {
            result.insert(key.to_string(), values.iter().map(|v| v.to_string()).collect());
        }

        let json = to_json_string(&result);
        println!("{}", json);

        if let Some(ref output_path) = output {
            let mut file = match fs::File::create(output_path) {
                Ok(f) => f,
                Err(e) => {
                    eprintln!("Error creating output file: {}", e);
                    std::process::exit(1);
                }
            };
            if let Err(e) = file.write_all(json.as_bytes()) {
                eprintln!("Error writing to output file: {}", e);
                std::process::exit(1);
            }
        }

        if reload {
            let config_path = config.unwrap_or_else(|| get_default_config_path());
            if let Err(e) = fs::write(&config_path, json) {
                eprintln!("Error writing to config file: {}", e);
                std::process::exit(1);
            }
            println!("Theme applied to {}", config_path);
        }
    } else {
        eprintln!("Unknown theme: {}", theme_arg);
        std::process::exit(1);
    }
}
